#!/usr/bin/env node
// SPDX-License-Identifier: MIT
// Generated by metaharness — the `my-bot` CLI entry point.
//
// This is plain ESM JavaScript on purpose: it runs as-is via `npx my-bot`
// with NO build step. `npm run build` (tsc) is only needed if you extend the
// TypeScript in src/. The published package ships this file directly (see the
// "bin" + "files" fields in package.json), so `npx my-bot` works the moment
// `npm install` has resolved @metaharness/kernel + @metaharness/host-claude-code.

import { loadKernel } from '@metaharness/kernel';
import adapter from '@metaharness/host-claude-code';
import readline from 'node:readline';

const HARNESS_NAME = 'my-bot';

/** `my-bot init` — boot the kernel + host adapter and report status. */
async function init() {
  const kernel = await loadKernel();
  const info = kernel.kernelInfo();
  console.log(`${HARNESS_NAME} — kernel ${info.version} (${kernel.backend})`);
  console.log(`Host adapter: ${adapter.name}`);
  console.log(`Run \`${HARNESS_NAME} doctor\` to verify the install.`);
  return 0;
}

/** `my-bot doctor` — verify the install end-to-end (kernel + host resolve). */
async function doctor() {
  const kernel = await loadKernel();
  const info = kernel.kernelInfo();
  const checks = [
    ['kernel loads', !!kernel],
    ['kernel reports a version', typeof info.version === 'string' && info.version.length > 0],
    ['kernel backend is native|wasm|js', ['native', 'wasm', 'js'].includes(kernel.backend)],
    ['host adapter has a name', typeof adapter?.name === 'string' && adapter.name.length > 0],
  ];
  let ok = true;
  for (const [label, pass] of checks) {
    console.log(`${pass ? 'PASS' : 'FAIL'} ${label}`);
    if (!pass) ok = false;
  }
  console.log(
    ok
      ? `\n${HARNESS_NAME}: all checks passed (kernel ${info.version}, ${kernel.backend} backend, host ${adapter.name})`
      : `\n${HARNESS_NAME}: doctor found problems`,
  );
  return ok ? 0 : 1;
}

/**
 * MCP (Model Context Protocol) JSON-RPC server over stdio.
 * Supports two modes:
 *   `my-bot mcp start`       — my-bot agent harness MCP server
 *   `my-bot mcp market-data` — market data proxy MCP server
 *
 * Communicates via JSON-RPC 2.0 on stdin/stdout.
 * All diagnostic output goes to stderr to keep stdout clean for the protocol.
 */
async function mcpServer(serverType) {
  const serverName = serverType === 'market-data'
    ? 'market_data'
    : 'my-bot';
  const serverVersion = '0.2.0';

  // Tool definitions for each server type
  const tools = serverType === 'market-data'
    ? [
        {
          name: 'read_price',
          description: 'Read current price and basic indicators for a ticker',
          inputSchema: {
            type: 'object',
            properties: {
              ticker: { type: 'string', description: 'Ticker code, e.g. 000300.SH or 1810.HK' },
            },
            required: ['ticker'],
          },
        },
        {
          name: 'read_macro',
          description: 'Read macro economic indicators',
          inputSchema: {
            type: 'object',
            properties: {
              indicator: { type: 'string', description: 'Indicator name or code, e.g. CPI, PMI, M2' },
            },
            required: ['indicator'],
          },
        },
      ]
    : [
        {
          name: 'get_status',
          description: 'Get my-bot harness status (paper/live mode, circuit breaker state)',
          inputSchema: { type: 'object', properties: {} },
        },
        {
          name: 'get_pipeline',
          description: 'Get current pipeline stage and skill chain status',
          inputSchema: { type: 'object', properties: {} },
        },
      ];

  // Read JSON-RPC requests from stdin line by line
  const rl = readline.createInterface({ input: process.stdin });
  for await (const line of rl) {
    if (!line.trim()) continue;
    let request;
    try {
      request = JSON.parse(line);
    } catch {
      const err = JSON.stringify({ jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null });
      process.stdout.write(err + '\n');
      continue;
    }

    const { method, params, id } = request;

    if (method === 'initialize') {
      process.stdout.write(JSON.stringify({
        jsonrpc: '2.0',
        id,
        result: {
          protocolVersion: '2024-11-05',
          capabilities: { tools: {} },
          serverInfo: { name: serverName, version: serverVersion },
        },
      }) + '\n');
    } else if (method === 'notifications/initialized') {
      // No response needed for notifications
    } else if (method === 'tools/list') {
      process.stdout.write(JSON.stringify({
        jsonrpc: '2.0',
        id,
        result: { tools },
      }) + '\n');
    } else if (method === 'tools/call') {
      const { name, arguments: args } = params;
      try {
        // Route to the kernel for actual execution
        const kernel = await loadKernel();
        const result = await kernel.callTool(serverName, name, args ?? {});
        process.stdout.write(JSON.stringify({
          jsonrpc: '2.0',
          id,
          result: { content: [{ type: 'text', text: JSON.stringify(result) }] },
        }) + '\n');
      } catch (err) {
        process.stdout.write(JSON.stringify({
          jsonrpc: '2.0',
          id,
          result: { content: [{ type: 'text', text: `Error: ${err.message}` }], isError: true },
        }) + '\n');
      }
    } else {
      process.stdout.write(JSON.stringify({
        jsonrpc: '2.0',
        id,
        error: { code: -32601, message: `Method not found: ${method}` },
      }) + '\n');
    }
  }
  return 0;
}

/**
 * Dispatch one CLI invocation. Exported (not just run on import) so a test can
 * drive it without spawning a subprocess. Returns the intended exit code.
 */
export async function run(argv) {
  const cmd = argv[0] ?? 'init';
  switch (cmd) {
    case 'init':
      return init();
    case 'doctor':
      return doctor();
    case 'mcp': {
      const sub = argv[1] ?? 'start';
      if (sub === 'start' || sub === 'market-data') {
        return mcpServer(sub === 'market-data' ? 'market-data' : 'start');
      }
      console.error(`Unknown MCP server: ${sub}. Use \`mcp start\` or \`mcp market-data\`.`);
      return 2;
    }
    case '--version':
    case '-v': {
      const kernel = await loadKernel();
      console.log(kernel.version());
      return 0;
    }
    case '--help':
    case '-h':
      console.log(`Usage: ${HARNESS_NAME} <command>\n\n  init            boot the kernel + host adapter (default)\n  doctor          verify the install end-to-end\n  mcp start       start the my-bot MCP server (stdio JSON-RPC)\n  mcp market-data start the market data MCP server\n  --version       print the kernel version`);
      return 0;
    default:
      console.error(`Unknown command: ${cmd}. Try \`${HARNESS_NAME} --help\`.`);
      return 2;
  }
}

// CLI guard: execute only when invoked directly (not when imported by a test).
// npm's bin shims pass a NON-normalized argv[1] (e.g. ".../.bin/../<pkg>/bin/cli.js"
// on Windows) and may differ in case, so realpath BOTH sides before comparing —
// a naive string === misses the npx/shim path and the CLI silently no-ops.
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { argv } from 'node:process';
const invokedDirectly = (() => {
  if (!argv[1]) return false;
  try {
    const a = realpathSync(argv[1]);
    const b = realpathSync(fileURLToPath(import.meta.url));
    return process.platform === 'win32' ? a.toLowerCase() === b.toLowerCase() : a === b;
  } catch {
    return false;
  }
})();
if (invokedDirectly) {
  run(argv.slice(2))
    .then((code) => process.exit(code))
    .catch((err) => {
      console.error(err);
      process.exit(1);
    });
}
